import os,urllib.request,urllib.error
base=os.environ['MCPJAM_API_URL']
for p in ['/usage','/credits','/billing','/projects','/account']:
 req=urllib.request.Request(base+p,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY']})
 try:
  r=urllib.request.urlopen(req,timeout=5);print(p,r.status,r.read().decode())
 except urllib.error.HTTPError as e:print(p,e.code,e.read().decode())
